import http from 'node:http';
const identities = new Map([['Bearer token-a', 'alice'], ['Bearer token-b', 'bob']]);
http.createServer(async (req, res) => {
  const actor = identities.get(req.headers.authorization);
  if (!actor) { res.writeHead(401); res.end(); return; }
  if (req.method !== 'GET' || req.url !== '/profile') { res.writeHead(404); res.end(); return; }
  const headers = {...req.headers, 'x-principal': actor};
  const reply = await fetch('http://profiles.internal/profile', {headers});
  res.writeHead(reply.status); res.end(await reply.text());
}).listen(8080);

