profiles = {"alice": {"private_email": "alice@private.test"}, "bob": {"private_email": "bob@private.test"}}
@app.get("/profile")
def profile():
    actor = request.headers.get("X-Principal")
    if actor not in profiles:
        return jsonify(error="unauthorized"), 401
    return jsonify(profiles[actor])

